from abc import ABCMeta, abstractmethod
from .log_file_provider_strategy import LogFileProviderStrategy
from .bip.airphone import AirphoneBipLogFileProvider


class UeLogFileProviderStrategy(LogFileProviderStrategy, metaclass=ABCMeta):
    @abstractmethod
    def get_bip_log_file(self, log_directory, collector_config):
        pass


class AirphoneLogFileProviderStrategy(
        AirphoneBipLogFileProvider,
        UeLogFileProviderStrategy):
    pass
